// Some portions generated by Claude
package org.eclipse.rdf4j.spin.function;

import static org.assertj.core.api.Assertions.assertThat;

import java.util.ServiceLoader;
import java.util.Set;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.query.algebra.evaluation.function.Function;
import org.eclipse.rdf4j.spin.function.spif.CurrentTimeMillis;
import org.eclipse.rdf4j.spin.function.spif.GenerateUUID;
import org.eclipse.rdf4j.spin.function.spif.Invoke;
import org.eclipse.rdf4j.spin.function.spif.Random;
import org.junit.jupiter.api.Test;

/**
 * The optimizer treats every registered function as repeatable unless it declares
 * {@link Function#mustReturnDifferentResult()}. This pins down which of the SPIN functions registered through
 * {@link ServiceLoader} make that declaration, so that a new nondeterministic function cannot silently become eligible
 * for filter relocation, constant folding or learned statistics.
 */
class RegisteredSpinFunctionVolatilityTest {

	@Test
	void onlyClockRandomAndArbitraryDispatchFunctionsAreVolatile() {
		Set<Class<?>> registered = ServiceLoader.load(Function.class)
				.stream()
				.map(ServiceLoader.Provider::type)
				.filter(type -> type.getPackageName().startsWith("org.eclipse.rdf4j.spin"))
				.collect(Collectors.toSet());
		Set<Class<?>> volatileFunctions = ServiceLoader.load(Function.class)
				.stream()
				.map(ServiceLoader.Provider::get)
				.filter(function -> registered.contains(function.getClass()))
				.filter(Function::mustReturnDifferentResult)
				.map(Object::getClass)
				.collect(Collectors.toSet());

		assertThat(registered).hasSizeGreaterThan(volatileFunctions.size());
		assertThat(volatileFunctions).containsExactlyInAnyOrder(CurrentTimeMillis.class, GenerateUUID.class,
				Invoke.class, Random.class);
	}
}
